WITH sales_agg AS ( SELECT ss.ss_item_sk AS item_sk, ss.ss_sold_date_sk AS sold_date_sk, ss.ss_sold_time_sk AS sold_time_sk, SUM(ss.ss_net_profit) AS sales_profit FROM store_sales ss GROUP BY ss.ss_item_sk, ss.ss_sold_date_sk, ss.ss_sold_time_sk ), returns_agg AS ( SELECT cr.cr_item_sk AS item_sk, cr.cr_returned_date_sk AS returned_date_sk, cr.cr_returned_time_sk AS returned_time_sk, cr.cr_warehouse_sk AS warehouse_sk, SUM(cr.cr_net_loss) AS return_loss, SUM(cr.cr_return_amount) AS return_amount FROM catalog_returns cr GROUP BY cr.cr_item_sk, cr.cr_returned_date_sk, cr.cr_returned_time_sk, cr.cr_warehouse_sk ) SELECT w.w_warehouse_name, sa.item_sk, sa.sales_profit, ra.return_loss, (sa.sales_profit - ra.return_loss) AS net_profit, CASE WHEN (sa.sales_profit - ra.return_loss) < 0 THEN 'Loss' ELSE 'Profit' END AS profit_status, t.t_hour AS sale_hour, DENSE_RANK() OVER (PARTITION BY w.w_warehouse_name ORDER BY (sa.sales_profit - ra.return_loss) DESC) AS profit_rank FROM sales_agg sa JOIN returns_agg ra ON sa.item_sk = ra.item_sk AND sa.sold_date_sk = ra.returned_date_sk JOIN warehouse w ON ra.warehouse_sk = w.w_warehouse_sk JOIN time_dim t ON sa.sold_time_sk = t.t_time_sk ORDER BY w.w_warehouse_name, profit_rank
